export function solve(initial: Record<string, string>, operations: any[]): any {
  const style = { ...initial },
    reads: string[] = [];
  const set = (k: string, v: string): void => {
    if (v === "") delete style[k];
    else style[k] = v;
  };
  for (const op of operations) {
    if (op.kind === "get") reads.push(style[op.property] ?? "");
    else if (op.kind === "set") set(op.property, op.value);
    else for (const k of Object.keys(op.values)) set(k, op.values[k]);
  }
  return { style, reads };
}
